#include <bits/stdc++.h>
using namespace std;

int main() {
    char a[2][2], b[2][2];

    for (auto &row : a)
        for (char &cell : row)
            cin >> cell;

    for (auto &row : b)
        for (char &cell : row)
            cin >> cell;

    const int r[4] = {0, 0, 1, 1};
    const int c[4] = {0, 1, 1, 0};

    vector<char> target;
    for (int i = 0; i < 4; ++i)
        if (a[r[i]][c[i]] != 'X')
            target.push_back(a[r[i]][c[i]]);

    for (int shift = 0; shift < 4; ++shift) {
        vector<char> current;
        for (int i = 0; i < 4; ++i) {
            int p = (i + shift) % 4;
            if (b[r[p]][c[p]] != 'X')
                current.push_back(b[r[p]][c[p]]);
        }

        if (current == target) {
            cout << "YES";
            return 0;
        }
    }

    cout << "NO";
    return 0;
}

