int main() {
    char a[2][2], b[2][2];

    for (int i = 0; i < 2; ++i)
        for (int j = 0; j < 2; ++j)
            cin >> a[i][j];

    for (int i = 0; i < 2; ++i)
        for (int j = 0; j < 2; ++j)
            cin >> b[i][j];

    const int order[4][2] = {{0, 0}, {0, 1}, {1, 1}, {1, 0}};
    vector<char> v1, v2;

    for (auto &p : order) {
        if (a[p[0]][p[1]] != 'X')
            v1.push_back(a[p[0]][p[1]]);
        if (b[p[0]][p[1]] != 'X')
            v2.push_back(b[p[0]][p[1]]);
    }

    if (v1.size() != v2.size()) {
        cout << "NO";
        return 0;
    }

    if (v1.empty()) {
        cout << "YES";
        return 0;
    }

    for (size_t shift = 0; shift < v2.size(); ++shift) {
        bool same = true;
        for (size_t i = 0; i < v1.size(); ++i) {
            if (v1[i] != v2[(i + shift) % v2.size()]) {
                same = false;
                break;
            }
        }
        if (same) {
            cout << "YES";
            return 0;
        }
    }

    cout << "NO";
    return 0;
}

